check_same <- function(e1, e2) {
  if (length(e1@eif) != length(e2@eif)) {
    stop("Length of @eif must be the same")
  }

  if (!identical(e1@weights, e2@weights)) {
    stop("@weights must be the same")
  }

  if (!identical(e1@id, e2@id)) {
    stop("@id must be the same")
  }

  invisible()

conf_int = new_property(
  getter = function(self) {
    self@x + c(-1, 1)*self@std_error*self@critical_value
  }

constructor = function(x, eif,
                       weights = rep(1, length(eif)),
                       id = as.character(1:length(eif)),
                       critical_value = qnorm(0.975)) {
  self <- new_object(
    S7_object(),
    x = x,
    eif = eif,
    weights = weights,
    id = id,
    critical_value = critical_value,
    std_error = NA_real_
  )

  S7::validate(self)

  self@std_error <- std_error(self)
  self
},
validator = function(self) {
  if (length(self@x) != 1) {
    return("@x must be length 1")
  }

  if (length(self@eif) <= 1) {
    return("@eif must be greather than length 1")
  }

  if (length(self@weights) != length(self@eif)) {
    return("@weights must be same length as @eif")
  }

  if (length(self@id) != length(self@eif)) {
    return("@id must be same length as @eif")
  }

  if (length(self@critical_value) != 1) {
    return("@critical_value must be length 1")
  }

  if (anyNA(self@eif)) {
    return("@eif must not contain `NA`")
  }

  if (anyNA(self@weights)) {
    return("@weights must not contain `NA`")
  }

  if (anyNA(self@id)) {
    return("@id must not contain `NA`")
  }
}

# x + y
method(`+`, list(influence_func_estimate, influence_func_estimate)) <- function(e1, e2) {
  check_same(e1, e2)
  influence_func_estimate(e1@x + e2@x, e1@eif + e2@eif, e1@weights, e1@id, max(e1@critical_value, e2@critical_value))
}

method(`+`, list(influence_func_estimate, class_numeric)) <- function(e1, e2) {
  influence_func_estimate(e1@x + e2, e1@eif, e1@weights, e1@id, e1@critical_value)
}

# Delegate to ife + scalar since addition is commutative
method(`+`, list(class_numeric, influence_func_estimate)) <- function(e1, e2) e2 + e1

# x - y
method(`-`, list(influence_func_estimate, influence_func_estimate)) <- function(e1, e2) {
  check_same(e1, e2)
  influence_func_estimate(e1@x - e2@x, e1@eif - e2@eif, e1@weights, e1@id, max(e1@critical_value, e2@critical_value))
}

method(`-`, list(influence_func_estimate, class_numeric)) <- function(e1, e2) {
  influence_func_estimate(e1@x - e2, e1@eif, e1@weights, e1@id, e1@critical_value)
}

method(`-`, list(class_numeric, influence_func_estimate)) <- function(e1, e2) {
  influence_func_estimate(e1 - e2@x, -e2@eif, e2@weights, e2@id, e2@critical_value)
}

# x / y
method(`/`, list(influence_func_estimate, influence_func_estimate)) <- function(e1, e2) {
  check_same(e1, e2)
  if (abs(e2@x) < .Machine$double.eps) {
    stop("Division by zero: denominator estimate is zero", call. = FALSE)
  }
  eif <- (e1@eif / e2@x) - ((e2@eif / e2@x^2) * e1@x)
  influence_func_estimate(e1@x / e2@x, eif, e1@weights, e1@id, max(e1@critical_value, e2@critical_value))
}

method(`/`, list(class_numeric, influence_func_estimate)) <- function(e1, e2) {
  if (abs(e2@x) < .Machine$double.eps) {
    stop("Division by zero: denominator estimate is zero", call. = FALSE)
  }
  influence_func_estimate(e1 / e2@x, -e1 / e2@x^2 * e2@eif, e2@weights, e2@id, e2@critical_value)
}

method(`/`, list(influence_func_estimate, class_numeric)) <- function(e1, e2) {
  if (abs(e2) < .Machine$double.eps) {
    stop("Division by zero: denominator is zero", call. = FALSE)
  }
  influence_func_estimate(e1@x / e2, 1 / e2 * e1@eif, e1@weights, e1@id, e1@critical_value)
}

# x * y
method(`*`, list(influence_func_estimate, influence_func_estimate)) <- function(e1, e2) {
  check_same(e1, e2)
  influence_func_estimate(e1@x * e2@x, e2@x * e1@eif + e1@x * e2@eif, e1@weights, e1@id, max(e1@critical_value, e2@critical_value))
}

method(`*`, list(class_numeric, influence_func_estimate)) <- function(e1, e2) {
  influence_func_estimate(e1 * e2@x, e1 * e2@eif, e2@weights, e2@id, e2@critical_value)
}

# x^n
method(`^`, list(influence_func_estimate, class_numeric)) <- function(e1, e2) {
  influence_func_estimate(e1@x^e2, e2 * e1@x^(e2 - 1) * e1@eif, e1@weights, e1@id, e1@critical_value)
}

# Delegate to scalar * ife since multiplication is commutative
method(`*`, list(influence_func_estimate, class_numeric)) <- function(e1, e2) e2 * e1

# log(x)
method(log, influence_func_estimate) <- function(x, base) {
  if (x@x <= 0) {
    stop("log() requires positive values: estimate is ", x@x, call. = FALSE)
  }
  influence_func_estimate(log(x@x), x@eif / x@x, x@weights, x@id, x@critical_value)
}

# exp(x)
method(exp, influence_func_estimate) <- function(x) {
  influence_func_estimate(exp(x@x), exp(x@x) * x@eif, x@weights, x@id, x@critical_value)

# print
method(print, influence_func_estimate) <- function(x, ...) {
  ci <- x@conf_int
  div <- cli_div(theme = list(.val = list(digits = 3)))
  cli({
    cat(format_inline("      Estimate: {.val {x@x}}\n"))
    cat(format_inline("    Std. error: {.val {x@std_error}}\n"))
    cli_text("95% Conf. int.: {.val {ci[1]}}, {.val {ci[2]}}")
  })
  cli_end(div)

std_error <- function(self) {
  weighted_eif <- self@eif * self@weights
  n_clusters <- length(unique(self@id))
  n <- length(weighted_eif)

  # No clustering, or if only 1 cluster, treat as unclustered (all observations independent)
  if (n_clusters == length(weighted_eif) | n_clusters == 1) {
    return(sqrt(fvar(weighted_eif) / length(weighted_eif)))
  } 

  # Multiple clusters: use cluster-robust variance (see doi: 10.1002/sim.9813)
  cluster_sums <- fsum(weighted_eif, self@id)
  cluster_eif <- cluster_sums * n_clusters / n
  sqrt(fvar(cluster_eif) / n_clusters)
}

method(tidy, influence_func_estimate) <- function(x) {
  out <- data.frame(
    estimate = x@x,
    std.error = x@std_error,
    conf.low = x@conf_int[1],
    conf.high = x@conf_int[2]
  )
  class(out) <- c("tbl_df", "tbl", "data.frame")
  out

# For a sample mean, the EIF is x_i - mean(x).
# SE = sqrt(var(eif) / n) = sd(x) / sqrt(n) in the unclustered case.

describe("unclustered (default: each observation is its own cluster)", {
  it("SE of sample mean equals sd(x) / sqrt(n)", {
    set.seed(42)
    x <- rnorm(50, mean = 5, sd = 2)
    obj <- ife(mean(x), x - mean(x))
    expect_equal(obj@std_error, sd(x) / sqrt(length(x)), tolerance = tol)
  })
})

describe("single cluster", {
  it("falls back to unclustered formula when all ids are the same", {
    set.seed(42)
    x <- rnorm(50, mean = 5, sd = 2)
    unclustered <- ife(mean(x), x - mean(x))
    one_cluster <- ife(mean(x), x - mean(x), id = rep("A", length(x)))
    expect_equal(one_cluster@std_error, unclustered@std_error, tolerance = tol)

eif <- function(density_ratios, shifted, natural, time, time_horizon) {
  if (missing(time_horizon)) time_horizon <- ncol(density_ratios)
  if (missing(time)) time <- 1
  residuals <- shifted[, (time + 1):(time_horizon + 1), drop = FALSE] - natural[, time:time_horizon, drop = FALSE]
  rowSums(compute_weights(density_ratios, time, time_horizon) * residuals, na.rm = TRUE) + shifted[, time]
}

compute_weights <- function(density_ratios, time, time_horizon) {
  out <- t(apply(density_ratios[, time:time_horizon, drop = FALSE], 1, cumprod))
  if (ncol(out) > ncol(density_ratios)) return(t(out))
  out
}

